/**
 * Repair feature types — mirrors shared types for frontend use.
 */

// ============================================================================
// Repair Status
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Color mapping for status badges */
export const STATUS_COLORS: Record<RepairStatus, string> = {
  intake: 'bg-blue-100 text-blue-800',
  in_progress: 'bg-yellow-100 text-yellow-800',
  on_hold: 'bg-orange-100 text-orange-800',
  verified: 'bg-purple-100 text-purple-800',
  ready: 'bg-green-100 text-green-800',
  completed: 'bg-gray-100 text-gray-800',
  cancelled: 'bg-red-100 text-red-800',
}

// ============================================================================
// Repair Detail Shape (matches API response)
// ============================================================================

export interface RepairDetail {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: 'waiting_parts' | 'awaiting_customer_approval' | 'other' | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

/** Repair detail enriched with customer name and bicycle info for list display */
export interface RepairDetailWithCustomer extends Omit<RepairDetail, 'bicycleId'> {
  customerName: string | null
  bicycleBrand: string
  bicycleModel: string
  bicycleColor: string | null
}

// ============================================================================
// Intake Form Types
// ============================================================================

/** Customer selection mode */
export type CustomerMode = 'existing' | 'new'

/** Bicycle selection mode */
export type BicycleMode = 'select_existing' | 'create_new'

/** Compact customer shape for selectors — matches GET /api/customers response. */
export interface IntakeCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

/** Compact bicycle shape for selectors */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer with their bicycles — returned during intake lookup */
export interface CustomerWithBicycles extends IntakeCustomer {
  bicycles: IntakeBicycle[]
}

/** Form data for the repair intake modal */
export interface RepairIntakeFormData {
  // Customer section
  customerMode: CustomerMode
  existingCustomerId?: string
  newFirstName?: string
  newLastName?: string
  newCompanyName?: string
  newPhone: string
  newEmail: string

  // Bicycle section
  bicycleMode: BicycleMode
  existingBicycleId?: string
  newBrand: string
  newModel: string
  newColor: string

  // Notes
  customerNotes: string

  // Optional scheduling dates (epoch ms, nullable)
  plannedDate?: number | null
  pickupDate?: number | null
}

/** Default empty form state */
export const createEmptyIntakeForm = (): RepairIntakeFormData => ({
  customerMode: 'existing',
  newPhone: '',
  newEmail: '',
  bicycleMode: 'select_existing',
  newBrand: '',
  newModel: '',
  newColor: '',
  customerNotes: '',
})

/**
 * Repair List Page
 *
 * Shows all active repairs with status color-coding, customer name, bicycle info,
 * assigned worker, planned date, and pickup date. Managers can filter by status,
 * assigned worker, and pickup date (today/this week). Default sorting is by
 * planned_date descending (most urgent first).
 */

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Calendar,
  Plus,
  User,
  Filter,
  X,
} from 'lucide-react'
import { STATUS_COLORS, type RepairStatus, type RepairDetailWithCustomer } from '../types.js'
import { RepairIntakeModal } from './RepairIntakeModal.js'

// ---------------------------------------------------------------------------
// Types for API response and filter options
// ---------------------------------------------------------------------------

interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

interface RepairListFilters {
  status?: RepairStatus | ''
  assignedTo?: string | 'unassigned'
  pickupDate?: 'today' | 'this_week'
}

// ---------------------------------------------------------------------------
// API function — fetches paginated repair list with filters
// ---------------------------------------------------------------------------

async function fetchRepairs(
  filters: RepairListFilters,
  page: number = 1,
): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(page))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Helper — format date for display
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

// ---------------------------------------------------------------------------
// Helper — get worker name (simplified; in production this would fetch from users API)
// ---------------------------------------------------------------------------

function getWorkerName(assignedTo: string | null, workers: WorkerOption[]): string {
  if (!assignedTo) return 'Unassigned'
  const worker = workers.find((w) => w.id === assignedTo)
  return worker?.name ?? 'Unknown'
}

interface WorkerOption {
  id: string
  name: string
}

// ---------------------------------------------------------------------------
// Component — Repair List Page
// ---------------------------------------------------------------------------

export function RepairListPage() {
  const navigate = useNavigate()
  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Filter state
  const [filters, setFilters] = useState<RepairListFilters>({
    status: undefined,
    assignedTo: undefined,
    pickupDate: undefined,
  })
  const [showFilters, setShowFilters] = useState(false)

  // Workers list (would come from users API in production)
  const [workers, setWorkers] = useState<WorkerOption[]>([])

  // Intake modal open state
  const [showIntakeModal, setShowIntakeModal] = useState(false)

  // Fetch repairs on filter/page change
  const loadRepairs = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const result = await fetchRepairs(filters, currentPage)
      setRepairs(result.repairs)
      setTotalPages(result.totalPages)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load repairs')
    } finally {
      setLoading(false)
    }
  }, [filters, currentPage])

  // Load workers list
  useEffect(() => {
    fetch('/api/users')
      .then((r) => r.json())
      .then((data: WorkerOption[]) => setWorkers(data))
      .catch(() => setWorkers([]))
  }, [])

  // Initial load and filter changes
  useEffect(() => {
    loadRepairs()
  }, [loadRepairs])

  const handleFilterChange = (key: keyof RepairListFilters, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value || undefined }))
    setCurrentPage(1) // Reset to first page when filters change
  }

  const clearFilters = () => {
    setFilters({ status: undefined, assignedTo: undefined, pickupDate: undefined })
    setCurrentPage(1)
  }

  const hasActiveFilters = filters.status || filters.assignedTo || filters.pickupDate

  // Status options for filter dropdown
  const statusOptions: { value: RepairStatus | ''; label: string }[] = [
    { value: '', label: 'All statuses' },
    { value: 'intake', label: 'Intake' },
    { value: 'in_progress', label: 'In Progress' },
    { value: 'on_hold', label: 'On Hold' },
    { value: 'verified', label: 'Verified' },
    { value: 'ready', label: 'Ready for Pickup' },
    { value: 'completed', label: 'Completed' },
  ]

  // Worker options for filter dropdown
  const workerOptions: WorkerOption[] = [
    { id: 'unassigned', name: 'Unassigned' },
    ...workers,
  ]

  return (
    <div className="p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-foreground">Repair List</h1>
        <div className="flex gap-2">
          <button
            onClick={() => setShowIntakeModal(true)}
            className="flex items-center gap-2 px-3 py-2 rounded-lg border bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
          >
            <Plus size={16} />
            Add Repair
          </button>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 px-3 py-2 rounded-lg border transition-colors ${
            showFilters || hasActiveFilters
              ? 'border-primary bg-primary/5 text-primary'
              : 'border-border hover:bg-muted'
          }`}
        >
          <Filter size={16} />
          Filters {hasActiveFilters && `(${Object.values(filters).filter(Boolean).length})`}
        </button>
        </div>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className="mb-4 p-4 border rounded-lg bg-card">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-sm font-semibold text-muted-foreground uppercase">Filters</h2>
            {hasActiveFilters && (
              <button onClick={clearFilters} className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1">
                <X size={12} /> Clear all
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            {/* Status Filter */}
            <div>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Status</label>
              <select
                value={filters.status ?? ''}
                onChange={(e) => handleFilterChange('status', e.target.value)}
                className="w-full px-3 py-2 border rounded-lg bg-background text-sm"
              >
                {statusOptions.map((opt) => (
                  <option key={opt.value || 'all'} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Worker Filter */}
            <div>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Assigned To</label>
              <select
                value={filters.assignedTo ?? ''}
                onChange={(e) => handleFilterChange('assignedTo', e.target.value)}
                className="w-full px-3 py-2 border rounded-lg bg-background text-sm"
              >
                {workerOptions.map((opt) => (
                  <option key={opt.id} value={opt.id}>
                    {opt.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Pickup Date Filter */}
            <div>
              <label className="block text-xs font-medium text-muted-foreground mb-1">Pickup Date</label>
              <select
                value={filters.pickupDate ?? ''}
                onChange={(e) => handleFilterChange('pickupDate', e.target.value)}
                className="w-full px-3 py-2 border rounded-lg bg-background text-sm"
              >
                <option value="">All dates</option>
                <option value="today">Today</option>
                <option value="this_week">This Week</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Results */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      ) : error ? (
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      ) : repairs.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          No repairs found{hasActiveFilters ? ' with the selected filters' : ''}
        </div>
      ) : (
        <>
          {/* Table */}
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full">
              <thead className="bg-muted/50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Status</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Customer</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Bicycle</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Assigned To</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Planned Date</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-muted-foreground tracking-wider">Pickup Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {repairs.map((repair) => (
                  <tr
                    key={repair.id}
                    onClick={() => navigate(`/repairs/${repair.id}`)}
                    className="hover:bg-muted/30 cursor-pointer transition-colors"
                  >
                    {/* Status Badge */}
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${STATUS_COLORS[repair.status]}`}>
                        {repair.status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())}
                      </span>
                    </td>

                    {/* Customer Name */}
                    <td className="px-4 py-3 text-sm text-foreground">
                      {repair.customerName || '—'}
                    </td>

                    {/* Bicycle Info */}
                    <td className="px-4 py-3 text-sm text-muted-foreground">
                      <div>{repair.bicycleBrand}</div>
                      <div className="text-xs">{repair.bicycleModel}{repair.bicycleColor ? ` · ${repair.bicycleColor}` : ''}</div>
                    </td>

                    {/* Assigned Worker */}
                    <td className="px-4 py-3 text-sm">
                      <div className="flex items-center gap-1.5 text-muted-foreground">
                        <User size={14} />
                        {getWorkerName(repair.assignedTo, workers)}
                      </div>
                    </td>

                    {/* Planned Date */}
                    <td className="px-4 py-3 text-sm text-muted-foreground">
                      <div className="flex items-center gap-1.5">
                        <Calendar size={14} />
                        {formatDate(repair.plannedDate)}
                      </div>
                    </td>

                    {/* Pickup Date */}
                    <td className="px-4 py-3 text-sm text-muted-foreground">
                      <div className="flex items-center gap-1.5">
                        <Calendar size={14} />
                        {formatDate(repair.pickupDate)}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-4">
              <p className="text-sm text-muted-foreground">
                Showing page {currentPage} of {totalPages} ({repairs.length} repairs)
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="px-3 py-1.5 text-sm border rounded-lg disabled:opacity-50 hover:bg-muted"
                >
                  Previous
                </button>
                <button
                  onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                  disabled={currentPage === totalPages}
                  className="px-3 py-1.5 text-sm border rounded-lg disabled:opacity-50 hover:bg-muted"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </>
      )}

      {/* Intake Modal */}
      <RepairIntakeModal
        open={showIntakeModal}
        onOpenChange={(open) => setShowIntakeModal(open)}
        onSuccess={() => {
          loadRepairs()
          setCurrentPage(1)
        }}
      />
    </div>
  )
}

/**
 * useRepairsForWeek — Data hook for the week calendar view.
 *
 * Fetches active repairs for a 7-day range (Mon–Sun) and provides
 * prev/next/today navigation. Returns epoch-ms boundaries so that
 * the UI can distribute repair cards into day columns.
 */

import { useState, useEffect, useCallback } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getRepairsForWeek } from '../api.js'

// ---------------------------------------------------------------------------
// Week boundary helpers (Mon–Sun, local time)
// ---------------------------------------------------------------------------

/** Get Monday 00:00:00.000 of the week containing `date` */
function mondayOf(date: Date): number {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun, 1=Mon ...
  const diffToMonday = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diffToMonday)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Hook interface
// ---------------------------------------------------------------------------

export interface UseRepairsForWeekOptions {
  /** Optional anchor date. Defaults to today. */
  initialDate?: Date
}

export interface UseRepairsForWeekReturn {
  repairs: RepairDetailWithCustomer[]
  weekStart: number // Monday 00:00:00.000 (epoch ms)
  weekEnd: number   // Sunday 23:59:59.999 (epoch ms)
  isLoading: boolean
  error: string | null
  goPrev: () => void
  goNext: () => void
  goToday: () => void
}

/**
 * Fetches repairs for a week range and provides navigation controls.
 */
export function useRepairsForWeek(options?: UseRepairsForWeekOptions): UseRepairsForWeekReturn {
  const anchorDate = options?.initialDate ?? new Date()

  // Track the current Monday to enable prev/next navigation
  const [weekMonday, setWeekMonday] = useState<number>(() => mondayOf(anchorDate))

  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  // Compute week boundaries from the current Monday anchor
  const weekStart = weekMonday
  const weekEnd = (() => {
    const sun = new Date(weekMonday)
    sun.setDate(sun.getDate() + 6)
    sun.setHours(23, 59, 59, 999)
    return sun.getTime()
  })()

  // Fetch repairs whenever the week range changes
  useEffect(() => {
    let cancelled = false

    const fetchRepairs = async () => {
      setIsLoading(true)
      setError(null)

      try {
        const result = await getRepairsForWeek(weekStart, weekEnd)
        if (!cancelled) {
          setRepairs(result.repairs)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to fetch repairs')
          setRepairs([])
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchRepairs()

    return () => {
      cancelled = true
    }
  }, [weekStart, weekEnd])

  // Navigation handlers — shift the Monday anchor by ±7 days
  const goPrev = useCallback(() => {
    setWeekMonday((prev) => prev - 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goNext = useCallback(() => {
    setWeekMonday((prev) => prev + 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goToday = useCallback(() => {
    setWeekMonday(mondayOf(new Date()))
  }, [])

  return { repairs, weekStart, weekEnd, isLoading, error, goPrev, goNext, goToday }
}

/**
 * Repair feature API client.
 */

import type {
  RepairDetail,
  RepairDetailWithCustomer,
  CustomerWithBicycles,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

interface RepairIntakeInput {
  customerMode: 'existing' | 'new'
  existingCustomerId?: string
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email?: string
  }
  bicycleMode: 'select_existing' | 'create_new'
  existingBicycleId?: string
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  customerNotes: string
  plannedDate?: number | null
  pickupDate?: number | null
}

interface StatusTransitionInput {
  targetStatus: RepairDetail['status']
  holdReason?: 'waiting_parts' | 'awaiting_customer_approval' | 'other'
  holdReasonNote?: string
}

interface NotesUpdateInput {
  customerNotes?: string | null
  internalNotes?: string | null
  plannedDate?: number | null
  pickupDate?: number | null
}

// ---------------------------------------------------------------------------
// API Functions
// ---------------------------------------------------------------------------

/** Create a new repair via the intake flow. */
export async function createRepair(input: RepairIntakeInput): Promise<RepairDetail> {
  const response = await fetch('/api/repairs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create repair' }))
    throw new Error(error.error || 'Failed to create repair')
  }

  return response.json()
}

/** Get a single repair by ID. */
export async function getRepair(id: string): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }

  return response.json()
}

/** Transition a repair's status. */
export async function transitionRepairStatus(id: string, input: StatusTransitionInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/transition`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to transition status' }))
    throw new Error(error.error || 'Failed to transition status')
  }

  return response.json()
}

/** Update repair notes. */
export async function updateRepairNotes(id: string, input: NotesUpdateInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/notes`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update notes' }))
    throw new Error(error.error || 'Failed to update notes')
  }

  return response.json()
}

/** Get a customer with their bicycles for intake selection. */
export async function getCustomerWithBicycles(customerId: string): Promise<CustomerWithBicycles> {
  const response = await fetch(`/api/repairs/customers/${customerId}`)

  if (!response.ok) {
    throw new Error('Failed to fetch customer with bicycles')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Timer API — POST /repairs/:id/timer/start & stop
// ---------------------------------------------------------------------------

export interface WorkLog {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  durationMs?: number
}

/** Start a manual work timer for a repair. Returns the created work log. */
export async function startWorkTimer(repairId: string, userId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to start timer' }))
    throw new Error(error.error || 'Failed to start work timer')
  }

  return response.json()
}

/** Stop an active work timer session. Returns the updated work log with duration. */
export async function stopWorkTimer(repairId: string, workLogId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/stop`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ workLogId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to stop timer' }))
    throw new Error(error.error || 'Failed to stop work timer')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Repair List API — GET /repairs
// ---------------------------------------------------------------------------

interface RepairListFilters {
  status?: string
  assignedTo?: string
  pickupDate?: 'today' | 'this_week'
  page?: number
  pageSize?: number
}

/** Get paginated repair list with optional filters. */
export async function getRepairs(filters: RepairListFilters = {}): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(filters.page ?? 1))
  params.set('pageSize', String(filters.pageSize ?? 20))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Payment Completion API — POST /repairs/:id/complete
// ---------------------------------------------------------------------------

export interface RepairPaymentMethod {
  method: 'cash' | 'card'
  amount: number
}

export interface CompleteRepairInput {
  payments: RepairPaymentMethod[]
}

export interface CompleteRepairResult {
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: 'completed'
    customerNotes: string | null
    internalNotes: string | null
    holdReason: string | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

// ---------------------------------------------------------------------------
// Week Calendar API — GET /repairs?from=&to=&statusIn=
// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

/**
 * Date anchor utility.
 *
 * Resolves a repair's display date for calendar placement:
 * - Primary: plannedDate (epoch ms)
 * - Fallback: createdAt when plannedDate is null/undefined
 */

export interface DateAnchorInput {
  plannedDate: number | null | undefined
  createdAt: number
}

/**
 * Returns the epoch-ms timestamp to anchor a repair card on the calendar.
 * Uses plannedDate if present; falls back to createdAt.
 */
export function getDateAnchor(input: DateAnchorInput): number {
  return input.plannedDate ?? input.createdAt
}
